return {
  guard: {
    hook: "onEvent", rateLimit: "oncePerRound",
    eventType: "threatSpent",
    promptOnPlayer: async (H, actor, ctx) => {
      const { zone, amount } = ctx.payload;
      if (H.zone.of(actor) !== zone) return false;
      if (!(await H.ask.confirm({
        title: "War of Attrition",
        bodyHtml: `The Entity spent <strong>${amount}</strong> Threat from <strong>${zone}</strong>. Guard as an immediate action?`,
        yesLabel: "Guard",
        noLabel: "Skip",
      }))) return false;
      await H.actions.guard(actor);
      return true;
    },
  },
};
